namespace Poe2Accessibility.Services
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Text.Json;

    /// <summary>
    ///     The dat columns names are read from, as tools/Poe2UiExtract found them in the player's own install
    ///     (catalog/dat-columns.json, regenerated by the launcher after a game patch): a column an update moved is
    ///     followed without a new build. Without the file, or for a column it lacks, the measured offset stays.
    /// </summary>
    public static class DatColumns
    {
        /// <summary>No row is this wide (the widest read, Mods, is 0x2B5 bytes): a larger offset is a broken file.</summary>
        private const int MaxColumn = 0x1000;

        public static void Apply(string path, PluginLog log)
        {
            Dictionary<string, int>? columns = null;
            try
            {
                columns = File.Exists(path) ? JsonSerializer.Deserialize<Dictionary<string, int>>(File.ReadAllText(path)) : null;
            }
            catch (Exception exception) when (exception is IOException or JsonException or UnauthorizedAccessException)
            {
                log.Warn($"Dat columns unreadable ({exception.Message}): names read where measured");
            }

            if (columns == null)
            {
                return;
            }

            Follow(columns, "Mods.Name", GameLayout.ModsDat.NameOffset, offset => GameLayout.ModsDat.NameOffset = offset, log);
            Follow(columns, "PassiveSkills.Name", GameLayout.PassiveTree.MeasuredRowNameOffset,
                offset => GameLayout.PassiveTree.RowShift = offset - GameLayout.PassiveTree.MeasuredRowNameOffset, log);
            Follow(columns, "ActiveSkills.DisplayedName", GameLayout.SkillSlot.DisplayedNameOffset, offset => GameLayout.SkillSlot.DisplayedNameOffset = offset, log);
        }

        private static void Follow(Dictionary<string, int> columns, string column, int measured, Action<int> use, PluginLog log)
        {
            if (!columns.TryGetValue(column, out var offset) || offset is <= 0 or >= MaxColumn)
            {
                log.Info($"Dat columns: {column} not found, read where measured (+0x{measured:X})");
                return;
            }

            use(offset);
            log.Info(offset == measured ? $"Dat columns: {column} where measured" : $"Dat columns: {column} moved from +0x{measured:X} to +0x{offset:X}");
        }
    }
}
